window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-d79a13437eaf9c08"]={"versions": [{"id": "FIG-d79a13437eaf9c08", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Anwendungsfalldiagramm (Use Case Diagram) mit funktionalen Systemgrenzen (<code>Diagnostic Execution</code>, <code>Fault Reaction</code>) und annotierten Constraints/Notizen.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Orchestrierungs- und Integrationskonzepts für Hardwarediagnosen (Pre-OS und Startup-Tests) innerhalb der AUTOSAR-Classic-Architektur über den BSW-Dienst <em>Hardware Test Manager</em> (HTM / HTMSS, Document ID 804).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen hardwarenaher Ausführung (BIST, µC Safety Library, MCAL) und übergeordneter Safety-Logik (Safety SW-C). Es definiert das Vertrauensmodell (<em>Trust Awareness</em>) bezüglich der MCU-Ressourcen vor und nach dem Start des AUTOSAR OS.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure (Actors)</p>\n<ul class=\"fig-list\">\n<li><strong><code>µC Hardware BIST</code>:</strong> Hardware-integrierter Built-In Self-Test der MCU (z. B. LBIST für Logik, MBIST für SRAMs).</li>\n<li><strong><code>µC Safety Library (non AUTOSAR) or MSTP</code>:</strong> Halbleiterhersteller-spezifische Testbibliothek (Microcontroller Software/Self-Test Package, z. B. Core-Tests, Peripherie-Selbsttests).</li>\n<li><strong><code>MCAL Driver</code> & <code>Complex Device Driver</code>:</strong> Basissoftware-Treiber mit dedizierten Diagnose-Schnittstellen (außerhalb der Standard-Init-Funktionen).</li>\n<li><strong><code>Custom Integrator Code</code>:</strong> Kundenspezifischer Startup-/Integrationscode (Bootcode vor oder während der BSW-Initialisierungssequenz).</li>\n<li><strong><code>HTM</code> (Hardware Test Manager):</strong> System Service Modul im BSW-Service-Layer zur Testorchestrierung und Ergebnisaggregation.</li>\n<li><strong><code>Safety SW-C</code>:</strong> Sicherheitsrelevante Software-Komponente oberhalb der RTE zur Festlegung deterministischer Systemreaktionen.</li>\n</ul>\n<p class=\"fig-p\">#### Anwendungsfälle (Use Cases) & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Execution of Diagnostics</code>:</strong> Wird von <code>Custom Integrator Code</code> über die Beziehung <code>«invokes»</code> aufgerufen; interagiert direkt mit <code>µC Safety Library / MSTP</code>, <code>MCAL Driver</code> und <code>Complex Device Driver</code>.</li>\n<li><strong><code>Critical Fault Detected</code>:</strong> Ausgelöst durch <code>µC Hardware BIST</code> oder <code>Custom Integrator Code</code>. Führt via Abhängigkeit <code>«invokes»</code> direkt zu <code>Fail-Safe State (Non-Operational State)</code>.</li>\n<li><strong><code>Test Result Collection</code>:</strong> Zentraler Sammelpunkt; aggregiert Testergebnisse aus <code>µC Hardware BIST</code> und <code>Custom Integrator Code</code> zur Übergabe an den <code>HTM</code>.</li>\n<li><strong><code>Representation of MCU State w.r.t diagnostics</code>:</strong> Abstrahiertes Zustandsmodell des HTM; stellt den Diagnose-/Integritätsstatus der MCU für die <code>Safety SW-C</code> bereit.</li>\n<li><strong><code>Functional Degradation / Limp Home</code> & <code>Fail-Safe State (Non-Operational State)</code>:</strong> Reaktionspfade der <code>Safety SW-C</code> bei erkannten Fehlern.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Phasenablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Power-On / Reset]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Pre-AUTOSAR Boot: Custom Integrator Code]</p>\n<p class=\"fig-p\">├─ Trigger: µC Hardware BIST / Safety Lib / MCAL Diag</p>\n<p class=\"fig-p\">├─ Fehlerfall (Kritisch): ──► Impliziter Reset / Execution Halt ──► [Fail-Safe State]</p>\n<p class=\"fig-p\">└─ Gutfall / Non-Critical:</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR Start: EcuM / BSW Init / OS Start]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[HTM Initialisierung]</p>\n<p class=\"fig-p\">└─ Test Result Collection (Ergebnisübernahme aus Pre-OS-Puffer/BIST-Registern)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[RTE Start]</p>\n<p class=\"fig-p\">└─ HTM stellt Status via RTE bereit ──► [Safety SW-C]</p>\n<p class=\"fig-p\">├─ Non-Critical: ──► [Degradation / Limp Home]</p>\n<p class=\"fig-p\">└─ Fatal/Critical: ──► [Fail-Safe State]</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Pre-OS / Pre-AUTOSAR Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Ausführung der <code>MCAL_Init()</code>-Routinen führt der <code>Custom Integrator Code</code> synchrone Basistests aus (<code>µC Hardware BIST</code>, <code>µC Safety Library</code>).</li>\n<li><strong>Kritischer Abbruch:</strong> Tritt ein unüberwindbarer Hardwaredefekt auf, greift das <em>Implicit Fault Reporting</em>: Der Controller verharrt im Reset oder hält die Befehlsausführung an. AUTOSAR wird nicht gestartet; das System befindet sich unmittelbar im <code>Fail-Safe State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BSW-Initialisierungsphase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werden keine fatalen Fehler erkannt, startet die BSW-Init-Kaskade.</li>\n<li>Der <code>HTM</code> wird im System Service Layer initialisiert und holt die Diagnosedaten (<code>Test Result Collection</code>) aus Hardwareregistern oder flüchtigen Übergabespeichern des Integratorcodes ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Post-OS / RTE-Laufzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Start des AUTOSAR OS steht die Service-Port-Schnittstelle des HTM an der RTE zur Verfügung.</li>\n<li>Die <code>Safety SW-C</code> liest den aggregierten Hardware-Zustand (<code>Representation of MCU State w.r.t diagnostics</code>) zyklisch oder ereignisorientiert aus und steuert das System:</li>\n<li><em>Limp Home:</em> Bei tolerierbaren Teilausfällen werden degraded Betriebsmodi aktiviert.</li>\n<li><em>Fail-Safe:</em> Bei funktional nicht kompensierbaren Fehlern wird ein kontrollierter Übergang in den sicheren Zustand erzwungen.</li>\n</ul>\n<hr class=\"fig-divider\" />\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>MCAL-Initialisierungsvertrag (Integrator-Constraint):</strong></li>\n</ul>\n<p class=\"fig-p\">Diagnosetests dürfen <strong>nicht</strong> innerhalb der standardisierten <code>Driver_Init()</code>-Funktionen der MCAL ausgeführt werden. Zeitintensive oder destruktive Tests (z. B. RAM-Pattern-Tests, Register-Mirror-Checks) müssen zwingend <strong>vor</strong> dem MCAL-Init über herstellerspezifische MCAL-Diagnose-Interfaces oder Safety-Libraries ausgeführt werden.</p>\n<ul class=\"fig-list\">\n<li><strong>Ergebnis-Persistierung über Reset-Grenzen:</strong></li>\n</ul>\n<p class=\"fig-p\">Da der HTM erst nach dem OS verfügbar ist, muss der <code>Custom Integrator Code</code> Diagnoseergebnisse aus der Pre-OS-Phase in reset-festen, nicht-initialisierten RAM-Sektionen (z. B. <code>.noinit</code>) oder dedizierten Hardware-Statusregistern puffern.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE-Verfügbarkeit & Schichtenentkopplung:</strong></li>\n</ul>\n<p class=\"fig-p\">Direkte Zugriffe von SW-Cs auf den HTM vor Abschluss des RTE-Starts sind architektonisch unzulässig. Der HTM fungiert als AUTOSAR-Standard-System-Service; die Anbindung an die Application-Layer-Safety-SW-C erfolgt ausschließlich über standardisierte Client/Server- oder Sender/Receiver-Ports via RTE.</p>\n<ul class=\"fig-list\">\n<li><strong>ISO 26262 Asymmetrie:</strong></li>\n</ul>\n<p class=\"fig-p\">Das Konzept trennt harte Hardwarefehler (Fail-Silent vor Boot) von applikativ behandelbaren Fehlern (Graceful Degradation / Limp-Home nach Boot), um die Sicherheitsziele (ASIL) ohne Deadlocks bei Systemstart zu erreichen.</p>"}, {"id": "FIG-034d490f16af974e", "releases": ["R20-11", "R21-11", "R22-11", "R23-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<ul class=\"fig-list\">\n<li><strong>Klassifikation:</strong> UML-Anwendungsfalldiagramm (Use Case Diagram) mit funktionalen Systemgrenzen (<code>Diagnostic Execution</code>, <code>Fault Reaction</code>) und annotierten Constraints/Notizen.</li>\n<li><strong>Technischer Zweck:</strong> Spezifikation des Orchestrierungs- und Integrationskonzepts für Hardwarediagnosen (Pre-OS und Startup-Tests) innerhalb der AUTOSAR-Classic-Architektur über den BSW-Dienst <em>Hardware Test Manager</em> (HTM / HTMSS, Document ID 804).</li>\n<li><strong>Architektonische Einordnung:</strong> Bindeglied zwischen hardwarenaher Ausführung (BIST, µC Safety Library, MCAL) und übergeordneter Safety-Logik (Safety SW-C). Es definiert das Vertrauensmodell (<em>Trust Awareness</em>) bezüglich der MCU-Ressourcen vor und nach dem Start des AUTOSAR OS.</li>\n</ul>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">#### Akteure (Actors)</p>\n<ul class=\"fig-list\">\n<li><strong><code>µC Hardware BIST</code>:</strong> Hardware-integrierter Built-In Self-Test der MCU (z. B. LBIST für Logik, MBIST für SRAMs).</li>\n<li><strong><code>µC Safety Library (non AUTOSAR) or MSTP</code>:</strong> Halbleiterhersteller-spezifische Testbibliothek (Microcontroller Software/Self-Test Package, z. B. Core-Tests, Peripherie-Selbsttests).</li>\n<li><strong><code>MCAL Driver</code> & <code>Complex Device Driver</code>:</strong> Basissoftware-Treiber mit dedizierten Diagnose-Schnittstellen (außerhalb der Standard-Init-Funktionen).</li>\n<li><strong><code>Custom Integrator Code</code>:</strong> Kundenspezifischer Startup-/Integrationscode (Bootcode vor oder während der BSW-Initialisierungssequenz).</li>\n<li><strong><code>HTM</code> (Hardware Test Manager):</strong> System Service Modul im BSW-Service-Layer zur Testorchestrierung und Ergebnisaggregation.</li>\n<li><strong><code>Safety SW-C</code>:</strong> Sicherheitsrelevante Software-Komponente oberhalb der RTE zur Festlegung deterministischer Systemreaktionen.</li>\n</ul>\n<p class=\"fig-p\">#### Anwendungsfälle (Use Cases) & Beziehungen</p>\n<ul class=\"fig-list\">\n<li><strong><code>Execution of Diagnostics</code>:</strong> Wird von <code>Custom Integrator Code</code> über die Beziehung <code>«invokes»</code> aufgerufen; interagiert direkt mit <code>µC Safety Library / MSTP</code>, <code>MCAL Driver</code> und <code>Complex Device Driver</code>.</li>\n<li><strong><code>Critical Fault Detected</code>:</strong> Ausgelöst durch <code>µC Hardware BIST</code> oder <code>Custom Integrator Code</code>. Führt via Abhängigkeit <code>«invokes»</code> direkt zu <code>Fail-Safe State (Non-Operational State)</code>.</li>\n<li><strong><code>Test Result Collection</code>:</strong> Zentraler Sammelpunkt; aggregiert Testergebnisse aus <code>µC Hardware BIST</code> und <code>Custom Integrator Code</code> zur Übergabe an den <code>HTM</code>.</li>\n<li><strong><code>Representation of MCU State w.r.t diagnostics</code>:</strong> Abstrahiertes Zustandsmodell des HTM; stellt den Diagnose-/Integritätsstatus der MCU für die <code>Safety SW-C</code> bereit.</li>\n<li><strong><code>Functional Degradation / Limp Home</code> & <code>Fail-Safe State (Non-Operational State)</code>:</strong> Reaktionspfade der <code>Safety SW-C</code> bei erkannten Fehlern.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">```</p>\n<p class=\"fig-p\">[Power-On / Reset]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[Pre-AUTOSAR Boot: Custom Integrator Code]</p>\n<p class=\"fig-p\">├─ Trigger: µC Hardware BIST / Safety Lib / MCAL Diag</p>\n<p class=\"fig-p\">├─ Fehlerfall (Kritisch): ──► Impliziter Reset / Execution Halt ──► [Fail-Safe State]</p>\n<p class=\"fig-p\">└─ Gutfall / Non-Critical:</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[AUTOSAR Start: EcuM / BSW Init / OS Start]</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[HTM Initialisierung]</p>\n<p class=\"fig-p\">└─ Test Result Collection (Ergebnisübernahme aus Pre-OS-Puffer/BIST-Registern)</p>\n<p class=\"fig-p\">│</p>\n<p class=\"fig-p\">▼</p>\n<p class=\"fig-p\">[RTE Start]</p>\n<p class=\"fig-p\">└─ HTM stellt Status via RTE bereit ──► [Safety SW-C]</p>\n<p class=\"fig-p\">├─ Non-Critical: ──► [Degradation / Limp Home]</p>\n<p class=\"fig-p\">└─ Fatal/Critical: ──► [Fail-Safe State]</p>\n<p class=\"fig-p\">```</p>\n<ol class=\"fig-list\">\n<li><strong>Pre-OS / Pre-AUTOSAR Phase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Vor Ausführung der <code>MCAL_Init()</code>-Routinen führt der <code>Custom Integrator Code</code> synchrone Basistests aus (<code>µC Hardware BIST</code>, <code>µC Safety Library</code>).</li>\n<li><strong>Kritischer Abbruch:</strong> Tritt ein unüberwindbarer Hardwaredefekt auf, greift das <em>Implicit Fault Reporting</em>: Der Controller verharrt im Reset oder hält die Befehlsausführung an. AUTOSAR wird nicht gestartet; das System befindet sich unmittelbar im <code>Fail-Safe State</code>.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>BSW-Initialisierungsphase:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Werden keine fatalen Fehler erkannt, startet die BSW-Init-Kaskade.</li>\n<li>Der <code>HTM</code> wird im System Service Layer initialisiert und holt die Diagnosedaten (<code>Test Result Collection</code>) aus Hardwareregistern oder flüchtigen Übergabespeichern des Integratorcodes ab.</li>\n</ul>\n<ol class=\"fig-list\">\n<li><strong>Post-OS / RTE-Laufzeit:</strong></li>\n</ol>\n<ul class=\"fig-list\">\n<li>Nach dem Start des AUTOSAR OS steht die Service-Port-Schnittstelle des HTM an der RTE zur Verfügung.</li>\n<li>Die <code>Safety SW-C</code> liest den aggregierten Hardware-Zustand (<code>Representation of MCU State w.r.t diagnostics</code>) zyklisch oder ereignisorientiert aus und steuert das System:</li>\n<li><em>Limp Home:</em> Bei tolerierbaren Teilausfällen werden degraded Betriebsmodi aktiviert.</li>\n<li><em>Fail-Safe:</em> Bei funktional nicht kompensierbaren Fehlern wird ein kontrollierter Übergang in den sicheren Zustand erzwungen.</li>\n</ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\">\n<li><strong>MCAL-Initialisierungsvertrag (Integrator-Constraint):</strong></li>\n</ul>\n<p class=\"fig-p\">Diagnosetests dürfen <strong>nicht</strong> innerhalb der standardisierten <code>Driver_Init()</code>-Funktionen der MCAL ausgeführt werden. Zeitintensive oder destruktive Tests (z. B. RAM-Pattern-Tests, Register-Mirror-Checks) müssen zwingend <strong>vor</strong> dem MCAL-Init über herstellerspezifische MCAL-Diagnose-Interfaces oder Safety-Libraries ausgeführt werden.</p>\n<ul class=\"fig-list\">\n<li><strong>Ergebnis-Persistierung über Reset-Grenzen:</strong></li>\n</ul>\n<p class=\"fig-p\">Da der HTM erst nach dem OS verfügbar ist, muss der <code>Custom Integrator Code</code> Diagnoseergebnisse aus der Pre-OS-Phase in reset-festen, nicht-initialisierten RAM-Sektionen (z. B. <code>.noinit</code>) oder dedizierten Hardware-Statusregistern puffern.</p>\n<ul class=\"fig-list\">\n<li><strong>RTE-Verfügbarkeit & Schichtenentkopplung:</strong></li>\n</ul>\n<p class=\"fig-p\">Direkte Zugriffe von SW-Cs auf den HTM vor Abschluss des RTE-Starts sind architektonisch unzulässig. Der HTM fungiert als AUTOSAR-Standard-System-Service; die Anbindung an die Application-Layer-Safety-SW-C erfolgt ausschließlich über standardisierte Client/Server- oder Sender/Receiver-Ports via RTE.</p>\n<ul class=\"fig-list\">\n<li><strong>ISO 26262 Asymmetrie:</strong></li>\n</ul>\n<p class=\"fig-p\">Das Konzept trennt harte Hardwarefehler (Fail-Silent vor Boot) von applikativ behandelbaren Fehlern (Graceful Degradation / Limp-Home nach Boot), um die Sicherheitsziele (ASIL) ohne Deadlocks bei Systemstart zu erreichen.</p>"}], "trans": [{"from": "FIG-d79a13437eaf9c08", "to": "FIG-034d490f16af974e", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
